  toque: () => inked('hat', [{ d: 'M-17.5,-28L-17,-37L17,-37L17.5,-28Q0,-26 -17.5,-28Z', fill: '#FFFFFF' }, { d: 'M-16,-36C-24,-40 -24,-54 -15,-55C-15,-64 -4,-67 1,-61C6,-67 17,-64 16,-55C25,-54 24,-40 16,-36Z', fill: '#FFFFFF' }]) + line('M-6,-37Q-7,-46 -5,-53M6,-37Q7,-46 5,-53', 0.6, '#C9C2D4'),
