  basket: (C) => inked('prop2', [{ d: `M${C[0] - 10},${C[1] + 9}L${C[0] + 10},${C[1] + 9}L${C[0] + 8},${C[1] + 20}Q${C[0]},${C[1] + 22} ${C[0] - 8},${C[1] + 20}Z`, fill: '#D9A45B' }, { circle: [C[0] - 5, C[1] + 7.6, 3.4], fill: '#E53935' }, { circle: [C[0] + 1, C[1] + 6.8, 3.6], fill: '#FFB300' }, { d: `M${C[0] + 4},${C[1] + 9}C${C[0] + 4},${C[1] + 2} ${C[0] + 7},${C[1] - 1} ${C[0] + 9},${C[1] + 1}C${C[0] + 8},${C[1] + 4} ${C[0] + 7},${C[1] + 7} ${C[0] + 7},${C[1] + 9}Z`, fill: '#43A047' }]) + line(`M${C[0] - 8},${C[1] + 9}Q${C[0] - 6},${C[1] - 5} ${C[0]},${C[1] - 2}Q${C[0] + 6},${C[1] - 5} ${C[0] + 8},${C[1] + 9}`, 1.2, '#A8722F') + line(`M${C[0] - 9},${C[1] + 13}L${C[0] + 9},${C[1] + 13}M${C[0] - 8.5},${C[1] + 16.5}L${C[0] + 8.5},${C[1] + 16.5}`, 0.5, '#A8722F'),
  hanger: (C) => line(`M${C[0]},${C[1] + 2}q0,3 2,3q2,0 2,-2`, 0.8, '#9AA3AE') + inked('prop', [{ d: `M${C[0] + 2},${C[1] + 6}L${C[0] + 13},${C[1] + 11}L${C[0] - 9},${C[1] + 11}Z`, fill: '#C9A36B' }, { d: `M${C[0] - 4},${C[1] + 11}L${C[0] + 8},${C[1] + 11}L${C[0] + 13},${C[1] + 34}Q${C[0] + 2},${C[1] + 37} ${C[0] - 9},${C[1] + 34}Z`, fill: '#F7C6D9' }]) + line(`M${C[0] - 4},${C[1] + 19}Q${C[0] + 2},${C[1] + 21} ${C[0] + 9},${C[1] + 19}`, 0.6),
  bags: (C) => inked('prop2', [{ d: `M${C[0] - 9},${C[1] + 6}L${C[0] + 2},${C[1] + 6}L${C[0] + 3},${C[1] + 21}L${C[0] - 10},${C[1] + 21}Z`, fill: '#FF6B6B' }, { d: `M${C[0] - 2},${C[1] + 9}L${C[0] + 9},${C[1] + 9}L${C[0] + 10},${C[1] + 22}L${C[0] - 3},${C[1] + 22}Z`, fill: '#FFD166' }]) + line(`M${C[0] - 6},${C[1] + 6}Q${C[0] - 3},${C[1] - 1} ${C[0]},${C[1] + 6}M${C[0] + 1},${C[1] + 9}Q${C[0] + 3},${C[1]} ${C[0] + 6},${C[1] + 9}`, 0.8) + `<circle cx="${C[0] + 3.6}" cy="${C[1] + 15.6}" r="2" fill="#FF6B6B"/>`,
  map: (C) => inked('prop', [{ d: `M${C[0] - 8},${C[1] - 18}L${C[0] - 2},${C[1] - 16}L${C[0] + 4},${C[1] - 18}L${C[0] + 10},${C[1] - 16}L${C[0] + 10},${C[1] - 2}L${C[0] + 4},${C[1] - 4}L${C[0] - 2},${C[1] - 2}L${C[0] - 8},${C[1] - 4}Z`, fill: '#FFFFFF' }], 0.7) + line(`M${C[0] - 2},${C[1] - 16}L${C[0] - 2},${C[1] - 2}M${C[0] + 4},${C[1] - 18}L${C[0] + 4},${C[1] - 4}`, 0.5, '#9AA3AE') + `<path d="M${C[0] - 6},${C[1] - 8}Q${C[0] + 1},${C[1] - 14} ${C[0] + 8},${C[1] - 10}" fill="none" stroke="#3BA7E5" stroke-width="1" stroke-dasharray="1.2 1"/><circle cx="${C[0] + 8}" cy="${C[1] - 10}" r="1.4" fill="#FF6B6B"/>`,
