function figure(c) {
  const b = BASES[c.base], sw = c.sw ?? (c.base === 'young' ? 16 : c.fem ? 18.5 : 21);
  const t = torso(b, c, sw);
  const chinY = b.sy - (c.base === 'young' ? 4.5 : 7);
  const [lp, rp] = c.pose; // screen-left arm, screen-right arm
  const L = arm(b, c, -1, lp, sw), R = arm(b, c, 1, rp, sw);
  const handC = (A) => [A.W[0] + A.dir[0] * b.hand * 0.9, A.W[1] + A.dir[1] * b.hand * 0.9];
  const skin = SKIN[c.skin];
  let s = `<ellipse cx="0" cy="1.2" rx="${sw + 6}" ry="3.4" fill="#2B2433" opacity="0.12"/>`;
  s += legs(b, c);
  { const hu = HAIR[c.id]().under; if (hu) s += `<g transform="translate(0,${f(chinY)}) scale(${f(b.h / 40)})">${inked('hair-under', [{ d: hu, fill: c.hairColor }])}</g>`; }
  s += inked('neck', [{ d: `M-4.6,${chinY - 4}L4.6,${chinY - 4}L5,${b.sy}L-5,${b.sy}Z`, fill: skin[1] }], 0.8);
  s += `<g id="torso">${inked('top', [{ d: t.d, fill: c.top }])}${c.details.map((k) => DETAILS[k](b, c, t, sw)).join('')}</g>`;
  if (c.flour) s += `<g id="flour" fill="#FFFFFF" opacity="0.85"><ellipse cx="4.6" cy="${b.wy + 9}" rx="2.6" ry="2.2"/>${[[-1.6, -3.6], [0.4, -4.4], [2.4, -4.2], [4.2, -3.2]].map(([x, y]) => `<ellipse cx="${4.6 + x * 0.9}" cy="${b.wy + 9 + y}" rx="0.7" ry="1.3"/>`).join('')}<ellipse cx="7.6" cy="${b.wy + 9.4}" rx="0.7" ry="1.2" transform="rotate(-40 7.6 ${b.wy + 9.4})"/><circle cx="-5" cy="${b.wy + 16}" r="0.8"/><circle cx="-3" cy="${b.wy + 18}" r="0.5"/></g>`;
  if (c.tape) s += line(`M-8,${b.sy - 2}C-7,${b.sy + 10} -9,${b.sy + 18} -8,${b.sy + 26}M8,${b.sy - 2}C7,${b.sy + 10} 9,${b.sy + 18} 8,${b.sy + 22}`, 2.2, '#F2D14B') + line(`M-8,${b.sy - 2}C-7,${b.sy + 10} -9,${b.sy + 18} -8,${b.sy + 26}M8,${b.sy - 2}C7,${b.sy + 10} 9,${b.sy + 18} 8,${b.sy + 22}`, 0.4, INK, ' stroke-dasharray="0.5 1.5"');
  if (c.headphones) s += inked('headphones', [{ d: `M-11,${b.sy - 3}Q0,${b.sy + 6} 11,${b.sy - 3}L11,${b.sy - 0.6}Q0,${b.sy + 8.6} -11,${b.sy - 0.6}Z`, fill: '#22223B' }, { circle: [-11, b.sy - 1.6, 3.6], fill: c.accent }, { circle: [11, b.sy - 1.6, 3.6], fill: c.accent }], 0.7);
  s += headGroup(c, b, chinY);
  // props held below the hand go behind the arm, raised ones in front of it
  const propL = c.props[0] ? PROPS[c.props[0]](handC(L)) : '', propR = c.props[1] ? PROPS[c.props[1]](handC(R)) : '';
  s += `<g id="prop-back">${['hang', 'rest'].includes(lp) ? propL : ''}${['hang', 'rest'].includes(rp) ? propR : ''}</g>`;
  s += `<g id="arms">${L.svg}${R.svg}</g>`;
  s += `<g id="prop">${['hang', 'rest'].includes(lp) ? '' : propL}${['hang', 'rest'].includes(rp) ? '' : propR}</g>`;
  return s;
}

// Face-only drawing (for pins and cards): the head with hat, centred on the face.
function headOnly(c) {
  const b = { ...BASES.adult, h: 40 }, hu = HAIR[c.id]().under;
  return (hu ? inked('hair-under', [{ d: hu, fill: c.hairColor }]) : '') + headGroup(c, b, 0);
}

